const body = $json.body ?? $json;

const str = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);

const respondioContactId = str(body.respondioContactId);
const message = str(body.message);
const csatUrl = str(body.csatUrl);

// SIMS only calls this webhook for tickets that carry a Respond.io contact id, so a
// missing one means the payload is not ours. Failing loudly here (rather than sending
// a half-formed message) shows up in the n8n execution list and as a non-2xx back to
// SIMS, which records the failure on the ticket.
if (!respondioContactId) {
  throw new Error('Payload carried no respondioContactId');
}
if (!message || !csatUrl) {
  throw new Error('Payload carried no CSAT message');
}

// The Respond.io node's `id` identifier type is numeric.
const numericContactId = Number(respondioContactId);
if (!Number.isFinite(numericContactId)) {
  throw new Error(`respondioContactId is not numeric: ${respondioContactId}`);
}

return {
  json: {
    ticketId: str(body.ticketId),
    contactId: numericContactId,
    phone: str(body.phone),
    merchantName: str(body.merchantName),
    csatUrl,
    message,
    idempotencyKey: str(body.idempotencyKey),
  },
};
